import 'package:flutter/material.dart';
import '../../data/models/chat_models.dart';
import 'reply_preview.dart';
class ChatInput extends StatefulWidget { const ChatInput({super.key, this.replyText, required this.onCancelReply, required this.onSend, required this.onAttachment}); final String? replyText; final VoidCallback onCancelReply; final ValueChanged<String> onSend; final ValueChanged<MessageType> onAttachment; @override State<ChatInput> createState() => _ChatInputState(); }
class _ChatInputState extends State<ChatInput> { final TextEditingController controller = TextEditingController(); @override void dispose() { controller.dispose(); super.dispose(); } @override Widget build(BuildContext context) => SafeArea(child: Column(mainAxisSize: MainAxisSize.min, children: <Widget>[if (widget.replyText != null) Padding(padding: const EdgeInsets.all(8), child: ReplyPreview(text: widget.replyText!, onClose: widget.onCancelReply)), Padding(padding: const EdgeInsets.all(10), child: Row(children: <Widget>[IconButton(onPressed: () => _attachments(context), icon: const Icon(Icons.add_circle_outline)), Expanded(child: TextField(controller: controller, decoration: const InputDecoration(hintText: 'اكتب رسالتك...'))), IconButton(onPressed: () { widget.onSend(controller.text); controller.clear(); }, icon: const Icon(Icons.send))]))])); void _attachments(BuildContext context) { showModalBottomSheet<void>(context: context, builder: (BuildContext context) => Padding(padding: const EdgeInsets.all(20), child: Wrap(spacing: 12, children: <Widget>[for (final MessageType type in <MessageType>[MessageType.image, MessageType.file, MessageType.voice]) ActionChip(avatar: Icon(type == MessageType.voice ? Icons.mic : Icons.attach_file), label: Text(type == MessageType.voice ? 'رسالة صوتية' : 'مرفق'), onPressed: () { widget.onAttachment(type); Navigator.pop(context); })]))); } }
